(* [comment removed for export] *)
Lemma bc_prefix : forall (Q : machine_state -> Prop) (m : mem) (sp : word) (lo shi tbp tep cbp srp cur0 src n : Z)
    (ra gp tp t0 t1 t2 s0 s1 a0 a1 a5 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  rw_cells asegs m tbp [C8 (Z_to_bv 64 srp); C8 (Z_to_bv 64 cur0)] ->
  rw_cells asegs m cbp [C8 (Z_to_bv 64 src); C8 (Z_to_bv 64 n)] ->
  1 <= n <= 2^40 -> 0 <= srp < 2^64 -> 0 <= cur0 < 2^64 -> 0 <= src < 2^64 -> 0 <= tep -> tep + 16 <= 2^47 ->
  stk asegs m lo (bv_unsigned sp) -> lo + MB_BCOPY_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned sp mod 16 = 0 -> mem_inv asegs m -> ACONST m ->
  (tbp + 16 <= lo \/ bv_unsigned sp <= tbp) -> (cbp + 16 <= lo \/ bv_unsigned sp <= cbp) ->
  tbp mod 8 = 0 -> accessible m tbp 16 -> cbp mod 8 = 0 -> accessible m cbp 16 ->
  (forall (m1 : mem) (b0 b1 : word),
     munch [(lo, bv_unsigned sp)]%Z m m1 -> wmono asegs m m1 -> mem_inv asegs m1 ->
     rw_cells asegs m1 (bv_unsigned sp + -96) [C8 (Z_to_bv 64 srp); C8 (Z_to_bv 64 cur0)] ->
     rw_cells asegs m1 (bv_unsigned sp + -80) [C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
     stk asegs m1 lo (bv_unsigned sp + -96) ->
     evt asegs Q (bc_st 0xbfd70 ra (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 tep 0 src n
                    b0 b1 (Z_to_bv 64 tbp) (Z_to_bv 64 tep) (Z_to_bv 64 cbp) a5 (Z_to_bv 64 (2^64 - 1)) a7 s4
